a-inset-bottom));color:rgba(255,255,255,.75);font-weight:800;font-size:13px;letter-spacing:2px;text-transform:uppercase}.attempt{position:absolute;left:18px;top:calc(72px + env(safe-area-inset-top));color:white;font-weight:900;font-size:13px;text-shadow:0 2px 4px #000}.pause{position:absolute;right:16px;top:calc(64px + env(safe-area-inset-top));width:42px;height:42px;border:2px solid rgba(255,255,255,.7);border-radius:50%;background:rgba(10,12,35,.45);pointer-events:auto;display:none}.pause:before,.pause:after{content:"";position:absolute;top:10px;width:5px;height:16px;background:white;border-radius:2px}.pause:before{left:12px}.pause:after{right:12px}.pause.show{display:block}.gameover{position:absolute;inset:0;display:none;place-items:center;pointer-events:auto;background:rgba(7,8,25,.55);backdrop-filter:blur(3px)}.gameover.show{display:grid}.card{text-align:center;color:white}.card h2{font-size:50px;margin:0 0 8px;text-transform:uppercase;text-shadow:0 5px 0 #6a287c}.card p{font-weight:800;color:#99eaff}.retry{border:0;border-radius:16px;padding:13px 24px;color:#24134a;background:white;font-weight:1000;text-transform:uppercase;box-shadow:0 6px 0 #af90cf;cursor:pointer}.retry:active{transform:translateY(4px);box-shadow:0 2px 0 #af90cf}@media(max-height:520px){.title{margin-bottom:12px}.play{width:82px;height:82px;border-width:7px}.play:before{border-top-width:17px;border-bottom-width:17px;border-left-width:28px}.hint{bottom:12px}}
