<body>
<canvas id="game"></canvas>
<div class="ui">
<div class="top"><div class="brand">NEON RUSH</div><div class="progress"><div class="bar" id="bar"></div></div></div>
<div class="attempt" id="attempt">ATTEMPT 1</div><button class="pause" id="pause" aria-label="Pause"></button>
<div class="menu" id="menu"><h1 class="title">GEOMETRY<small>DASH 3.3</small></h1><button class="play" id="play" aria-label="Play"></button><div class="hint">Tap / Space / Click to jump</div></div>
<div class="gameover" id="gameover"><div class="card"><h2 id="endTitle">CRASHED</h2><p id="percent">0%</p><button class="retry" id="retry">Retry</button></div></div>
</div>
<script>
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
let W,H,ground,scale;
function resize(){W=innerWidth;H=innerHeight;canvas.width=W*devicePixelRatio;canvas.height=H*devicePixelRatio;canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);scale=Math.max(.75,Math.min(1.25,H/720));ground=H*.76}resize();addEventListener('resize',resize);
const menu=document.getElementById('menu'),gameover=document.getElementById('gameover'),bar=document.getElementById('bar'),attemptEl=document.getElementById('attempt'),pauseBtn=document.getElementById('pause');
let state='menu',attempt=1,time=0,cam=0,speed=330,distance=0,last=0;
const level=()=>{const a=[];[560,760,960,1260,1450,1660,1880,2100,2320,2520,2780,3020,3220,3450,3660,3900,4160,4380,4600,4820,5050,5280,5500,5740,5980,6200].forEach((x,i)=>a.push({x,y:ground-44,w:44,h:44,type:i%5===3?'double':'spike'}));return a};let obstacles=level();
const player={x:W*.18,y:ground-44,w:44,h:44,vy:0,rot:0,dead:false};
const stars=Array.from({length:90},()=>({x:Math.random(),y:Math.random()*.65,s:Math.random()*2+1,a:Math.random()*.7+.2}));
function reset(){cam=0;distance=0;player.x=W*.18;player.y=ground-44;player.vy=0;player.rot=0;player.dead=false;obstacles=level();attemptEl.textContent='ATTEMPT '+attempt;bar.style.width='0%';}
function start(){attempt++;attemptEl.textContent='ATTEMPT '+attempt;reset();state='playing';menu.classList.add('hidden');gameover.classList.remove('show');pauseBtn.classList.add('show');last=performance.now()}
play.onclick=start;retry.onclick=start;pauseBtn.onclick=()=>{if(state==='playing')state='paused';else if(state==='paused'){state='playing';last=performance.now()}};
function jump(){if(state==='menu'){start();return}if(state==='gameover'||state==='paused')return;if(player.y>=ground-player.h-1){player.vy=-Math.sqrt(2*1800*scale);}}
addEventListener('keydown',e=>{if(e.code==='Space'||e.code==='ArrowUp'){e.prevent.preventDefault?.();jump()}if(e.code==='KeyR'&&state==='gameover')start();});
addEventListener('pointerdown',e=>{if(e.target.closest?.('button'))return;jump()});
function collide(o){const px=player.x+cam,py=player.y;const pad=7;return px+player.w-pad>o.x&&px+pad<o.x+o.w&&py+player.h-pad>o.y&&py+pad<o.y+o.h}
function die(){if(state!=='playing')return;state='gameover';player.dead=true;pauseBtn.classList.remove('show');const pct=Math.min(100,Math.floor(distance/6200*100));document.getElementById('percent').textContent=pct+'%';document.getElementById('endTitle').textContent=pct>95?'SO CLOSE':'CRASHED';setTimeout(()=>gameover.classList.add('show'),350)}
function update(dt){dt=Math.min(dt,.032);if(state==='paused')return;if(state==='playing'){distance+=speed*dt;cam=distance;player.vy+=1800*scale*dt;player.y+=player.vy*dt;if(player.y+player.h>=ground){player.y=ground-player.h;player.vy=0;player.rot=Math.round(player.rot/(Math.PI/2))*Math.PI/2}else player.rot+=dt*5.2;if(player.y>H+100)die();for(const o of obstacles)if(collide(o)){die();break}if(distance>=6200){state='gameover';pauseBtn.classList.remove('show');document.getElementBy('percent').textContent='100%';document.getElementById('endTitle').textContent='COMPLETE';setTimeout(()=>gameover.classList.add('show'),350)}bar.style.width=Math.min(100,distance/6200*100)+'%'}}
function spike(x,y,w,h){ctx.beginPath();ctx.moveTo(x,y+h);ctx.lineTo(x+w*.5,y);ctx.lineTo(x+w,y+h);ctx.closePath();const g=ctx.createLinearGradient(x,y,x+w,y+h);g.addColorStop(0,'#effcff');g.addColorStop(.35,'#65d9ff');g.addColorStop(1,'#7b2bc3');ctx.fillStyle=g;ctx.fill();ctx.strokeStyle='#dffcff';ctx.lineWidth=3;ctx.stroke()}
function draw(){ctx.clearRect(0,0,W,H);const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#07091a');sky.addColorStop(.7,'#17113a');sky.addColorStop(1,'#32105a');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
ctx.fillStyle='rgba(255,255,255,.08)';for(const s of stars){const x=(s.x*W-cam*.03)%W;if(x<0)x+=W;ctx.globalAlpha=s.a;ctx.fillRect(x,s.y*H,s.s,s.s)}ctx.globalAlpha=1;
ctx.strokeStyle='rgba(118,72,172,.12)';ctx.lineWidth=1;for(let i=-1;i<12;i++){const x=((i*180-cam*.18)%2160+2160)%2160-180;ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=ground-360;y<ground;y+=70){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}
const floorX=-(cam*.9)%80;ctx.fillStyle='#11162e';ctx.fillRect(0,ground,W,H-ground);ctx.strokeStyle='#bd62ff';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(0,ground);ctx.lineTo(W,ground);ctx.stroke();ctx.fillStyle='rgba(98,58,145,.38)';for(let x=floorX;x<W;x+=80){ctx.beginPath();ctx.moveTo(x,ground);ctx.lineTo(x+40,ground+44);ctx.lineTo(x+80,ground);ctx.fill()}for(let x=-(cam*.25)%300;x<W;x+=300){ctx.fillStyle='rgba(88,227,255,.11)';ctx.fillRect(x,ground-150,180,150)}
for(const o of obstacles){const sx=o.x-cam;if(sx<-100||sx>W+100)continue;spike(sx,o.y,o.w,o.h)}
ctx.save();ctx.translate(player.x+player.w/2,player.y+player.h/2);ctx.rotate(player.rot);ctx.shadowBlur=22;ctx.shadowColor='#58ebff';ctx.fillStyle='#56e8ff';ctx.fillRect(-player.w/2,-player.h/2,player.w,player.h);ctx.shadowBlur=0;ctx.strokeStyle='#dffcff';ctx.lineWidth=4;ctx.strokeRect(-player.w/2+2,-player.h/2+2,player.w-4,player.h-4);ctx.fillStyle='#202c73';ctx.fillRect(-9,-9,18,18);ctx.restore();}
function loop(now){const dt=(now-last)/1000||0;last=now;update(dt);draw();requestAnimationFrame(loop)}reset();requestAnimationFrame(loop);
</script>
</body>
</html>
